"use client";

import type { CSSProperties, ReactNode } from "react";
import { Easing, interpolate, useCurrentFrame } from "remotion";

export type EndCardLayout = "16:9" | "9:16";
export type EndCardTheme = "light" | "dark";

export interface EndCardProps {
  /**
   * Logo mark rendered above the headline. Defaults to a built-in Acme mark;
   * pass `null` to hide it entirely.
   */
  logo?: ReactNode;
  /** The one closing line. Keep it short — this frame holds for seconds. */
  headline?: string;
  /** Label of the single CTA button — the only action on screen. */
  ctaLabel?: string;
  /** Plain destination rendered in mono under the CTA. */
  url?: string;
  /** Passive secondary slot (QR code, product badge, "Star on GitHub" chip). */
  badgeSlot?: ReactNode;
  /** Aspect preset: adjusts measure and vertical rhythm, not the copy. */
  layout?: EndCardLayout;
  theme?: EndCardTheme;
  /** One subtle 1.02 pulse on the CTA after entry, then perfectly still. */
  ctaPulse?: boolean;
  /**
   * Minimum frames the frame should hold static after all motion ends.
   * The scene never animates past its entrance + pulse — pair this with
   * `endCardDurationInFrames` to size the Sequence / Composition.
   */
  minHoldFrames?: number;
  /** CTA / accent color. */
  accentColor?: string;
  speed?: number;
  className?: string;
}

const FONT_FAMILY =
  'Inter, var(--font-geist-sans), -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';
const MONO_FAMILY =
  "'JetBrains Mono', var(--font-geist-mono), ui-monospace, SFMono-Regular, Menlo, monospace";

/** Last frame of the staggered entrance — everything is in place by here. */
export const ENTRANCE_FRAMES = 20;
/** Frame the single CTA pulse begins. */
export const PULSE_START = 26;
/** Length of the single CTA pulse (up and back down). */
export const PULSE_DURATION = 24;
/** Peak overscale of the pulse (1 → 1.02 → 1). */
export const PULSE_AMOUNT = 0.02;

/** Per-theme snap-cn palette for the end-card canvas. */
export const END_CARD_PALETTES: Record<
  EndCardTheme,
  {
    canvas: string;
    text: string;
    muted: string;
    border: string;
    markBg: string;
    markFg: string;
  }
> = {
  light: {
    canvas: "#FAFAFA",
    text: "#101828",
    muted: "#667085",
    border: "#E4E7EC",
    markBg: "#101828",
    markFg: "#FFFFFF",
  },
  dark: {
    canvas: "#0A0A0B",
    text: "#FAFAFA",
    muted: "#A1A1AA",
    border: "#26272B",
    markBg: "#FAFAFA",
    markFg: "#0A0A0B",
  },
};

/**
 * Exactly one soft pulse: 1 before `start`, a smooth 1 → 1 + amount → 1 arc
 * over `duration` frames, then 1 forever. Never repeats.
 */
export function pulseScale(
  frame: number,
  {
    enabled = true,
    start = PULSE_START,
    duration = PULSE_DURATION,
    amount = PULSE_AMOUNT,
  }: {
    enabled?: boolean;
    start?: number;
    duration?: number;
    amount?: number;
  } = {},
): number {
  if (!enabled || duration <= 0) return 1;
  const t = (frame - start) / duration;
  if (t <= 0 || t >= 1) return 1;
  // Half sine: eases up to the peak at t=0.5 and back down — no bounce.
  return 1 + amount * Math.sin(Math.PI * t);
}

/** First frame after which the scene is guaranteed fully static. */
export function staticFromFrame(ctaPulse: boolean): number {
  return ctaPulse ? PULSE_START + PULSE_DURATION : ENTRANCE_FRAMES;
}

/**
 * Suggested Sequence / Composition length: entrance (+ pulse) followed by at
 * least `minHoldFrames` of stillness — the research rule this scene encodes.
 */
export function endCardDurationInFrames(
  minHoldFrames = 90,
  ctaPulse = true,
): number {
  return staticFromFrame(ctaPulse) + Math.max(0, minHoldFrames);
}

/** Measure and vertical rhythm per aspect preset. */
export function layoutMetrics(layout: EndCardLayout): {
  headlineMaxWidth: number;
  logoGap: number;
  ctaGap: number;
  urlGap: number;
} {
  if (layout === "9:16") {
    return { headlineMaxWidth: 560, logoGap: 36, ctaGap: 44, urlGap: 24 };
  }
  return { headlineMaxWidth: 760, logoGap: 28, ctaGap: 36, urlGap: 20 };
}

/** Built-in fictional Acme logo mark (rounded square + geometric A). */
export function AcmeMark({
  background,
  foreground,
  size = 56,
}: {
  background: string;
  foreground: string;
  size?: number;
}) {
  return (
    <svg width={size} height={size} viewBox="0 0 56 56" fill="none" aria-hidden>
      <rect width={56} height={56} rx={14} fill={background} />
      <path d="M28 14L42 42H34.6L28 27.2L21.4 42H14L28 14Z" fill={foreground} />
      <rect x={24} y={34} width={8} height={4} rx={2} fill={background} />
    </svg>
  );
}

export function EndCard({
  logo,
  headline = "Start invoicing in minutes",
  ctaLabel = "Start free trial",
  url = "acme.dev",
  badgeSlot,
  layout = "16:9",
  theme = "light",
  ctaPulse = true,
  minHoldFrames = 90,
  accentColor = "#266DF0",
  speed = 1,
  className,
}: EndCardProps) {
  const frame = useCurrentFrame() * speed;
  // The hold is enforced by sizing the Sequence with `endCardDurationInFrames`;
  // referenced here so the prop and the schedule stay in one place.
  void minHoldFrames;

  const palette = END_CARD_PALETTES[theme] ?? END_CARD_PALETTES.light;
  const metrics = layoutMetrics(layout);
  const logoNode =
    logo === undefined ? (
      <AcmeMark background={palette.markBg} foreground={palette.markFg} />
    ) : (
      logo
    );

  const enter = (from: number, to: number): CSSProperties => ({
    opacity: interpolate(frame, [from, to], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }),
    translate: interpolate(frame, [from, to], ["0px 14px", "0px 0px"], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.cubic),
    }),
  });

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        textAlign: "center",
        backgroundColor: palette.canvas,
        fontFamily: FONT_FAMILY,
        padding: layout === "9:16" ? "0 48px" : "0 80px",
      }}
    >
      {logoNode ? (
        <div style={{ marginBottom: metrics.logoGap, ...enter(0, 12) }}>
          {logoNode}
        </div>
      ) : null}

      <h1
        style={{
          margin: 0,
          fontSize: 64,
          fontWeight: 600,
          lineHeight: 1.08,
          letterSpacing: "-0.02em",
          color: palette.text,
          maxWidth: metrics.headlineMaxWidth,
          ...enter(4, 18),
        }}
      >
        {headline}
      </h1>

      {/* The single action on screen. */}
      <div
        style={{
          marginTop: metrics.ctaGap,
          opacity: interpolate(frame, [8, 20], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          }),
          translate: interpolate(frame, [8, 20], ["0px 12px", "0px 0px"], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.out(Easing.cubic),
          }),
          scale:
            interpolate(frame, [8, 20], [0.97, 1], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
              easing: Easing.out(Easing.cubic),
            }) * pulseScale(frame, { enabled: ctaPulse }),
        }}
      >
        <div
          style={{
            display: "inline-flex",
            alignItems: "center",
            justifyContent: "center",
            height: 52,
            padding: "0 32px",
            borderRadius: 8,
            backgroundColor: accentColor,
            color: "#FFFFFF",
            fontSize: 18,
            fontWeight: 600,
            letterSpacing: "-0.01em",
            boxShadow: "0 8px 24px rgba(38,109,240,0.28)",
          }}
        >
          {ctaLabel}
        </div>
      </div>

      {url ? (
        <div
          style={{
            marginTop: metrics.urlGap,
            fontFamily: MONO_FAMILY,
            fontSize: 16,
            color: palette.muted,
            ...enter(12, 20),
          }}
        >
          {url}
        </div>
      ) : null}

      {badgeSlot ? (
        <div style={{ marginTop: 28, ...enter(12, 20) }}>{badgeSlot}</div>
      ) : null}
    </div>
  );
}
